def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents, take a safe minimal bid to get our requirement.
    if not alive_opps:
        return min(my_status.get('budget', 0.0), DAILY_SALARY * 0.35)

    # Read yesterday's behavior from previous_trace only.
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                prev_bids.append(b)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    # Determine aggressiveness from yesterday.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_highest = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_highest = 0.0

    # Pressure thresholds: infer if opponents are spending heavily.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85
    medium_pressure = highest_prev_bid >= DAILY_SALARY * 0.55

    # Safety adjustment: if low hp or already missing water, increase bid.
    urgency = 0
    if hp is not None and hp <= 2:
        urgency += 2
    if hp is not None and hp == 3:
        urgency += 1
    if no_water_days is not None and no_water_days >= 2:
        urgency += 2
    if no_water_days is not None and no_water_days == 1:
        urgency += 1

    # Supply-aware cap: if supply is tight relative to our requirement, bid more.
    # Use only int indices if needed; here we avoid indexing.
    supply_ratio = float(supply) / float(WATER_REQ) if WATER_REQ > 0 else 0.0
    tight_supply = supply_ratio < 2.0  # heuristic for medium/low supply

    # Base strategy
    if high_pressure:
        # Compete but don't overpay: slightly under their top bid unless urgency is high.
        target = highest_prev_bid * (0.92 if urgency <= 1 else 1.02)
        if tight_supply:
            target *= 1.10
    elif medium_pressure:
        target = max(DAILY_SALARY * 0.55, second_highest + (1.0 if urgency <= 1 else 2.0))
        if tight_supply:
            target *= 1.05
    else:
        # Low observed aggression: bid moderately to secure water for 9.
        target = DAILY_SALARY * (0.48 + 0.08 * urgency)
        if tight_supply:
            target *= 1.10

    # Ensure we never bid above budget.
    if budget is None:
        budget = 0.0
    bid = min(float(budget), float(target))

    # If urgency is extreme, ensure at least a strong bid.
    if urgency >= 3:
        bid = max(bid, min(float(budget), DAILY_SALARY * 0.85))

    # Keep bid non-negative.
    if bid < 0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_budget, 1) 

    CRITICAL_HP_THRESHOLD = 2 
    if my_hp <= CRITICAL_HP_THRESHOLD:
        slots_available = int(current_supply // WATER_REQ)
        if slots_available <= 1: 
            return min(my_budget, DAILY_SALARY * 0.95) 
        else: 
            return min(my_budget, DAILY_SALARY * 0.8)

    yesterday_bids = []
    opponent_water_requirements = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])
        opponent_water_requirements.append(opp['water_requirement'])

    estimated_slots = int(current_supply // WATER_REQ)
    if estimated_slots == 0:
        estimated_slots = 1 

    very_tight_supply = (estimated_slots <= 1 and num_alive_opponents >= 1) or \
                        (estimated_slots == 2 and num_alive_opponents >= 2)

    is_late_game = current_day >= EPISODE_DAYS * 0.7 

    base_bid = DAILY_SALARY * 0.5 

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)

        if very_tight_supply:
            if max_yesterday_bid >= DAILY_SALARY * 0.7:
                base_bid = max(base_bid, max_yesterday_bid + 5)
            else:
                base_bid = max(base_bid, avg_yesterday_bid * 1.2)

            if is_late_game:
                base_bid = max(base_bid, DAILY_SALARY * 0.75)

        else:
            if max_yesterday_bid >= DAILY_SALARY * 0.8:
                if my_hp > CRITICAL_HP_THRESHOLD + 1 and not is_late_game:
                    base_bid = min(base_bid, max_yesterday_bid * 0.8)
                else:
                    base_bid = max(base_bid, max_yesterday_bid * 0.9)
            else:
                base_bid = max(base_bid, avg_yesterday_bid + 2)
                if is_late_game:
                    base_bid = max(base_bid, DAILY_SALARY * 0.6)

    else:
        if very_tight_supply:
            base_bid = DAILY_SALARY * 0.7
        else:
            base_bid = DAILY_SALARY * 0.5 

    final_bid = max(1, base_bid)

    return min(my_budget, final_bid)
